import numpy as np

def centroid_defuzzify(xs, mus):
    xs_arr = np.asarray(xs, dtype=float)
    mus_arr = np.asarray(mus, dtype=float)
    denom = np.sum(mus_arr)
    if denom == 0:
        return 0.0
    return float(np.sum(xs_arr * mus_arr) / denom)

def sugeno_weighted_avg(weights, outputs):
    w_arr = np.asarray(weights, dtype=float)
    z_arr = np.asarray(outputs, dtype=float)
    denom = np.sum(w_arr)
    if denom == 0:
        return 0.0
    return float(np.sum(w_arr * z_arr) / denom)

import heapq

def dijkstra(graph, start, goal):
    pq = [(0, start)]
    distances = {start: 0}
    previous = {}
    visited = set()

    while pq:
        curr_dist, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            path = []
            cur = goal
            while cur in previous or cur == start:
                path.append(cur)
                if cur == start:
                    break
                cur = previous[cur]
            return curr_dist, path[::-1]

        for neighbor, weight in graph.get(node, []):
            new_dist = curr_dist + weight
            if new_dist < distances.get(neighbor, float('inf')):
                distances[neighbor] = new_dist
                previous[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    return float('inf'), []

def gradient_descent(x0, lr, steps):
    x = float(x0)
    for _ in range(steps):
        grad = 2.0 * (x - 3.0)
        x -= lr * grad
    return x

