def backward_chaining(goal, facts, rules, visited=None):
    if goal in facts:
        return True
    if visited is None:
        visited = set()
    if goal in visited:
        return False
    visited = visited | {goal}
    for premises, conclusion in rules:
        if conclusion == goal:
            if all(backward_chaining(p, facts, rules, visited) for p in premises):
                return True
    return False

