def combine_cf(cf1, cf2):
    if cf1 >= 0 and cf2 >= 0:
        return cf1 + cf2 * (1.0 - cf1)
    if cf1 < 0 and cf2 < 0:
        return cf1 + cf2 * (1.0 + cf1)
    denom = 1.0 - min(abs(cf1), abs(cf2))
    if denom == 0:
        return 0.0
    return (cf1 + cf2) / denom

