import numpy as np

def train_perceptron_and(lr=0.1, epochs=20):
    X = np.array([[0, 0], [0, 1], [1, 0], [1, 1]], dtype=float)
    Y = [0, 0, 0, 1]
    w = np.zeros(2, dtype=float)
    b = 0.0
    for _ in range(epochs):
        for x, y in zip(X, Y):
            y_hat = 1 if (np.dot(w, x) + b) >= 0 else 0
            err = y - y_hat
            w += lr * err * x
            b += lr * err
    return w, float(b)

