def gini_impurity(counts):
    total = sum(counts)
    if total == 0:
        return 0.0
    return 1.0 - sum((c / total) ** 2 for c in counts)

def weighted_gini_split(left_counts, right_counts):
    n_l = sum(left_counts)
    n_r = sum(right_counts)
    total = n_l + n_r
    if total == 0:
        return 0.0
    return (n_l / total) * gini_impurity(left_counts) + (n_r / total) * gini_impurity(right_counts)

import numpy as np

def q_learning_update(q_table, state, action, reward, next_state, alpha=0.1, gamma=0.9):
    best_next = np.max(q_table[next_state])
    td_target = reward + gamma * best_next
    q_table[state, action] += alpha * (td_target - q_table[state, action])
    return float(q_table[state, action])

