import numpy as np

def normalize_image(image):
    return np.asarray(image, dtype=float) / 255.0

def max_pool2d(feature_map, pool_size=2):
    arr = np.asarray(feature_map, dtype=float)
    h, w = arr.shape
    out_h, out_w = h // pool_size, w // pool_size
    out = np.zeros((out_h, out_w), dtype=float)
    for i in range(out_h):
        for j in range(out_w):
            out[i, j] = np.max(arr[i*pool_size:(i+1)*pool_size, j*pool_size:(j+1)*pool_size])
    return out

