import numpy as np

def compute_snr_db(signal, noise):
    p_sig = np.mean(np.asarray(signal, dtype=float) ** 2)
    p_noi = np.mean(np.asarray(noise, dtype=float) ** 2)
    return float(10.0 * np.log10(p_sig / p_noi))

def detect_speech_frames(frames, energy_threshold):
    res = []
    for f in frames:
        energy = float(np.mean(np.asarray(f, dtype=float) ** 2))
        res.append(energy >= energy_threshold)
    return res

